{
  "concepts": [
    {
      "concept_name": {
        "text": "abstract class",
        "refs": ["Q0000"]
      },
      "aliases": null,
      "content": {
        "text": "An abstract class is a class that cannot be instantiated with the new operator; it serves as a partial implementation that must be subclassed or accessed via other means.",
        "refs": ["Q0000"]
      }
    },
    {
      "concept_name": {
        "text": "factory method",
        "refs": ["Q0001"]
      },
      "aliases": null,
      "content": {
        "text": "A factory method is a static method that creates and returns an instance of a class, allowing object creation without using the new operator directly.",
        "refs": ["Q0001"]
      }
    },
    {
      "concept_name": {
        "text": "method overloading",
        "refs": ["Q0003"]
      },
      "aliases": null,
      "content": {
        "text": "Method overloading is the provision of multiple method signatures with the same name but different parameter types or counts, enabling the method to handle different argument types.",
        "refs": ["Q0003"]
      }
    },
    {
      "concept_name": {
        "text": "NumberFormat class",
        "refs": ["Q0000", "Q0001", "Q0004"]
      },
      "aliases": null,
      "content": {
        "text": "NumberFormat is an abstract class in Java that provides methods for formatting numbers as currency, percent, etc., and must be obtained via factory methods such as getCurrencyInstance() or getPercentInstance().",
        "refs": ["Q0000", "Q0001", "Q0004"]
      }
    }
  ],
  "definitions": [
    {
      "term": {
        "text": "abstract class",
        "refs": ["Q0000"]
      },
      "definition_text": {
        "text": "A class declared with the abstract keyword; it cannot be instantiated directly with new.",
        "refs": ["Q0000"]
      },
      "context": null
    },
    {
      "term": {
        "text": "factory method",
        "refs": ["Q0001"]
      },
      "definition_text": {
        "text": "A static method that creates and returns an instance of a class, acting as a “factory” for objects.",
        "refs": ["Q0001"]
      },
      "context": null
    },
    {
      "term": {
        "text": "method overloading",
        "refs": ["Q0003"]
      },
      "definition_text": {
        "text": "Having multiple methods with the same name but different parameter lists within the same class.",
        "refs": ["Q0003"]
      },
      "context": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "NumberFormat cannot be instantiated directly because it is abstract.",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "getCurrencyInstance() returns a NumberFormat object configured for currency formatting.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "getPercentInstance() returns a NumberFormat object configured for percent formatting.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "NumberFormat.format() can be overloaded to accept long, double, etc., and returns a formatted string.",
        "refs": ["Q0003"]
      },
      "fact_type": null
    }
  ],
  "examples": [
    {
      "example_type": null,
      "example_text": {
        "text": "NumberFormat currency = NumberFormat.getCurrencyInstance();\nString result = currency.format(1234567.891);\n// result → \"$1,234,567.89\" (depending on locale)",
        "refs": ["Q0001", "Q0002", "Q0003", "Q0004"]
      },
      "exemplifies": {
        "text": "Using a factory method to obtain a NumberFormat instance and formatting a number as currency.",
        "refs": ["Q0001", "Q0003"]
      }
    },
    {
      "example_type": null,
      "example_text": {
        "text": "NumberFormat percent = NumberFormat.getPercentInstance();\nString p = percent.format(0.85);\n// p → \"85%\"",
        "refs": ["Q0004"]
      },
      "exemplifies": {
        "text": "Obtaining a NumberFormat for percent formatting via a factory method.",
        "refs": ["Q0004"]
      }
    }
  ],
  "explanations": [
    {
      "topic": {
        "text": "Why NumberFormat is abstract",
        "refs": ["Q0000"]
      },
      "explanation_text": {
        "text": "NumberFormat provides a common API for different locale‑specific formatting strategies; the actual implementation is supplied by concrete subclasses created by the factory methods.",
        "refs": ["Q0000"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Renaming variables in IDE",
        "refs": ["Q0005"]
      },
      "explanation_text": {
        "text": "When a variable name is changed, the IDE can update all references automatically to avoid mismatched names.",
        "refs": ["Q0005"]
      },
      "explanation_type": null
    }
  ],
